import json
S="<scratch>"
d=json.load(open(S+"/p3out.json"))
for k,v in d.items():
    print("="*20,k,"subrc",v["subrc"])
    for m in v["messages"]:
        print("   MSG",m["type"],m["id"],m["number"],m["text"],"|",m["screen"])
    for t,rows in v["tables"].items():
        for r in rows:
            print("   ROW",t,{a:b for a,b in r.items() if b not in ("",0)})
PY

