input.content:
import json
import sys

d = json.load(open(sys.argv[1]))
for k, v in d.items():
    print("=" * 18, k, "subrc", v["subrc"])
    for m in v["messages"]:
        print("   MSG", m["type"], m["id"], m["number"], repr(m["text"]), "|", m["screen"])
    last = v["last"]
    if last.get("text") and not v["messages"]:
        print("   LAST", last["type"], last["id"], last["number"], repr(last["text"]))
    for t, rows in v["tables"].items():
        for r in rows:
            print("   ROW", t, {a: b for a, b in r.items() if b not in ("", 0)})

